@KafkaListener(topics = {
    "ledgerflow.ledger.wallet-hold.events.v1",
    "ledgerflow.ledger.wallet-release.events.v1",
    "ledgerflow.ledger.wallet-sale.events.v1" })
@Transactional
void onWalletEvent(EventEnvelope<?> e, Acknowledgment ack) {
    if (!processed.markProcessed(e.eventId(), GROUP)) { ack.acknowledge(); return; }
    walletMap.apply(e);            // idempotent, exactly as step 11 taught you
    ack.acknowledge();
}
